        title: '主动脉瓣疾病评估',
        sub: '狭窄 AS：AVA / DVI / 压差 三联 · 低流量低压差｜反流 AR：PISA · VC · PHT · RF｜脱垂与连枷 · 修复术后',
        source: ['R20', 'R43', 'R44', 'R81'],
        rel: ['asload', 'aortic-root', 'bav'],
        // ★ v1.4.4 合并：原「AS 主动脉瓣狭窄定量」「AR 主动脉瓣反流定量」两条并入本页，
